function subtreeWalk(session, oid, maxReps) {
    return new Promise(function(resolve) {
        const buf = [];
        session.subtree(oid, maxReps,
            function(vbs) { for (let i = 0; i < vbs.length; i++) buf.push(vbs[i]); },
            function(err) { resolve(buf); }
        );
    });
}

function pushIfValid(vb, out) {
    if (vb.value === null || vb.value === undefined) return;
