function buildBatchQueries(sysRows, netRows, ldiRows) { sysRows = Array.isArray(sysRows) ? sysRows : []; netRows = Array.isArray(netRows) ? netRows : []; ldiRows = Array.isArray(ldiRows) ? ldiRows : [];
    const queries = [];
    if (sysRows.length > 0) { const ph = sysRows.map((_, i) => { const b = i * 11; return `(NOW(),$${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8},$${b+9},$${b+10},$${b+11})`; }).join(','); const params = []; for (const r of sysRows) { params.push(r.device_id, r.cpu_cores, r.cpu_load_percent, r.ram_total_mb, r.ram_used_mb, r.ram_free_mb, r.disk_total_gb, r.disk_used_gb, r.disk_free_gb, r.disk_description, r.temp_c); } queries.push({ name: 'sys', count: sysRows.length, sql: 'INSERT INTO public.sys_metrics ("time",device_id,cpu_cores,cpu_load_percent,ram_total_mb,ram_used_mb,ram_free_mb,disk_total_gb,disk_used_gb,disk_free_gb,disk_description,temp_c) VALUES ' + ph, params: params }); }
    if (netRows.length > 0) { const ph = netRows.map((_, i) => { const b = i * 9; return `(NOW(),$${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8},$${b+9})`; }).join(','); const params = []; for (const r of netRows) { params.push(r.device_id, r.iface_name, r.rx_mbps, r.tx_mbps, r.rx_errors, r.tx_errors, r.rx_drops, r.tx_drops, r.status); } queries.push({ name: 'net', count: netRows.length, sql: 'INSERT INTO public.net_metrics ("time",device_id,iface_name,rx_mbps,tx_mbps,rx_errors,tx_errors,rx_drops,tx_drops,status) VALUES ' + ph, params: params }); }
    if (ldiRows.length > 0) { const ph = ldiRows.map((_, i) => { const b = i * 8; return `(NOW(),$${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8})`; }).join(','); const params = []; for (const r of ldiRows) { params.push(r.device_id, r.throughput, r.temperature, r.humidity, r.power_watt, r.vibration, r.pe_1, r.je_1); } queries.push({ name: 'ldi', count: ldiRows.length, sql: 'INSERT INTO public.ldi_metrics ("time",device_id,throughput,temperature,humidity,power_watt,vibration,pe_1,je_1) VALUES ' + ph, params: params }); }
    return queries;
}

const pool = global.get('pgPool');
if (!pool) { node.error('pgPool not available in global context'); return null; }
const sql = 'SELECT device_id AS machine_id, hostname, snmp_community AS community, snmp_port, device_type FROM public.devices WHERE enabled = true';
pool.query(sql, [], function(err, result) {
    if (err) {
        if (err.message && err.message.indexOf('does not exist') !== -1) {
            node.warn('Device Registry: table not ready yet — retrying in 10s');
        } else {
            node.warn('Device Registry: ' + err.message + ' — using fallback defaults');
        }
        return;
    }
    const registry = {};
    if (result && result.rows) {
        result.rows.forEach(function(row) {
            registry[row.machine_id] = {
                hostname: row.hostname || row.machine_id,
                community: row.community || 'public',
                snmp_port: row.snmp_port || 161,
                device_type: row.device_type || 'server'
            };
        });
    }
    flow.set('batchId', 'batch_' + Date.now());
    global.set('deviceRegistry', registry);
    node.log('Device registry loaded: ' + Object.keys(registry).length + ' devices');
});
return null;

const registry = global.get('deviceRegistry') || {};
const mid = msg.machine_id || msg.topic || '';
const device = registry[mid];
if (!device) {
    msg.host = msg.host || 'ims-snmpsim';
    msg.community = msg.community || 'Netk@';
    msg.snmp_port = msg.snmp_port || 161;
    msg.device_type = msg.device_type || 'server';
} else {
    msg.host = device.hostname;
    msg.community = device.community;
    msg.snmp_port = device.snmp_port;
    msg.device_type = device.device_type || 'server';
}
msg.machine_id = mid;
msg.topic = mid;
return msg;

const fs = global.get('fs');
const QUEUE_PATH = '/data/retry_queue.json';
fs.readFile(QUEUE_PATH, 'utf8', function(readErr, data) {
    let queue = [];
    try { if (!readErr && data) queue = JSON.parse(data); } catch(e) { queue = []; }
    const entry = {
        timestamp: new Date().toISOString(),
        retries: 0,
        sql: msg.query || '',
        params: msg.params || [],
        count: msg.count || 0,
        error: msg.error ? msg.error.message : 'unknown'
    };
    const oneHourAgo = Date.now() - 3600000;
    queue = queue.filter(function(e) { return new Date(e.timestamp).getTime() > oneHourAgo; });
    if (queue.length >= 500) queue = queue.slice(-499);
    queue.push(entry);
    fs.writeFile(QUEUE_PATH, JSON.stringify(queue), 'utf8', function(writeErr) {
        if (writeErr) node.error('Retry queue write failed: ' + writeErr.message);
        else node.warn('Retry: queued failed INSERT (#' + queue.length + ')');
    });
});
return msg;

const fs = global.get('fs');
const QUEUE_PATH = '/data/retry_queue.json';
const MAX_RETRIES = 5;
const pool = global.get('pgPool');
if (msg.payload !== 'drain') return null;
if (!pool) { node.warn('Retry: pgPool not available'); return null; }
fs.readFile(QUEUE_PATH, 'utf8', function(readErr, data) {
    if (readErr || !data) return;
    let queue = [];
    try { queue = JSON.parse(data); } catch(e) { return; }
    if (queue.length === 0) return;
    const entry = queue.shift();
    entry.retries++;
    if (entry.retries > MAX_RETRIES) {
        node.warn('Retry: dropped after ' + MAX_RETRIES + ' attempts');
        fs.writeFile(QUEUE_PATH, JSON.stringify(queue), 'utf8', function(){});
        return;
    }
    if (entry.sql && entry.params) {
        pool.query(entry.sql, entry.params, function(err) {
            if (err) {
                node.error('Retry [' + entry.retries + '/' + MAX_RETRIES + '] failed: ' + err.message);
                queue.unshift(entry);
            } else {
                node.log('Retry [' + entry.retries + '/' + MAX_RETRIES + '] ok: ' + entry.count + ' rows');
            }
            fs.writeFile(QUEUE_PATH, JSON.stringify(queue), 'utf8', function(){});
        });
    } else {
        node.warn('Retry: entry has no sql/params, skipping');
        fs.writeFile(QUEUE_PATH, JSON.stringify(queue), 'utf8', function(){});
    }
});
return null;

var expectedKey = env.get('INGEST_API_KEY');
var providedKey = msg.req ? msg.req.headers['x-api-key'] : null;

// 1. Auth Check (Send ORIGINAL msg to output 2)
if (expectedKey && providedKey !== expectedKey) {
    msg.statusCode = 401;
    msg.payload = JSON.stringify({ error: 'Unauthorized' });
    msg.headers = { 'Content-Type': 'application/json' };
    return [null, msg];
}

var body = msg.payload;
if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch(e) { body = {}; }
}

var machineId = body.machine_id || '';
if (!machineId) {
