}
if (machineId.startsWith('K6-SERVER-')) machineId = machineId.replace('K6-SERVER-', 'E2E-SERVER-');

// 2. Prepare Pipeline msg (Safely Clone to drop req/res and prevent memory leaks)
var pipelineMsg = {}; // Fix memory leak (no cloneMessage)
pipelineMsg.machine_id = machineId;
pipelineMsg.topic = machineId;
pipelineMsg.payload = '';

// 3. Prepare HTTP Response (Use ORIGINAL msg for output 2)
msg.statusCode = 200;
msg.payload = JSON.stringify({ ok: true, machine_id: machineId });
msg.headers = { 'Content-Type': 'application/json' };

return [pipelineMsg, msg];

const metrics = global.get('pipelineMetrics') || { inserts_ok: 0, inserts_failed: 0, last_flush: 0, devices_polled: 0, buffer_overflows: 0 };
const cb = global.get('circuitBreaker');
const lines = [
    '# HELP ims_pipeline_inserts_total Total successful DB inserts',
    '# TYPE ims_pipeline_inserts_total counter',
    'ims_pipeline_inserts_total ' + metrics.inserts_ok,
    '# HELP ims_pipeline_inserts_failed_total Total failed DB inserts',
    '# TYPE ims_pipeline_inserts_failed_total counter',
    'ims_pipeline_inserts_failed_total ' + metrics.inserts_failed,
    '# HELP ims_pipeline_last_flush_timestamp_seconds Last successful flush epoch',
