    '# HELP ims_pipeline_buffer_overflows_total Total records dropped to prevent OOM',
    '# TYPE ims_pipeline_buffer_overflows_total counter',
    'ims_pipeline_buffer_overflows_total ' + (metrics.buffer_overflows || 0)
];
if (cb) {
    const cbMetrics = cb.renderMetrics(flow);
    if (cbMetrics) lines.push(cbMetrics);
