// ══════════════════════════════════════════════════════════════════
// LDI ALARM SIMULATOR — noise codes (real distribution, uncorrelated
// equipment/calibration faults) + condition-driven codes (fired only
// when the matching telemetry parameter is actually out of spec right
// now, per the same thresholds v_ldi_alarm_context/migration 045 uses).
//
// IMS-FULL-SYSTEM-AUDIT.md P0-2: previously every code (including the
// process-linked ones like 91009/90005/91008/70004) was drawn from a
// pure Poisson/weighted-random process independent of telemetry, so
// the RCA Truth Test correctly reported Lift ≈ 1 (no correlation to
// find, because there was none by construction). Codes with a known
// real-world parameter link now only fire when that parameter is
// actually out of spec, so Lift should rise meaningfully (> 2).
//
// VACUUM (91009) is deliberately NOT made condition-driven here: DF
// INNER's air_vacuum recipe constant (~-16 to -19) and DF OUTER/SM's
// "not applicable" 0.0 sentinel are BOTH already > -50, so
// flag_vac_out_of_spec is true for ~100% of all rows regardless of
// timing (baseline ≈ 100%, confirmed in the audit's RCA table). No
// alarm-timing strategy can raise Lift above ~1 when the baseline
// itself is saturated — that's a flag-threshold/recipe mismatch for
// someone with the real vendor vacuum spec to resolve (migration 045),
// not something to fake a fix for here. 91009 stays in the noise pool.
// ══════════════════════════════════════════════════════════════════
const pool = global.get('pgPool');
if (!pool) { node.status({ fill: 'red', shape: 'ring', text: 'no pgPool' }); return null; }

// codes with no known telemetry correlation - unconditioned background noise
const NOISE_CUM = [["91009", 26.9], ["93004", 44.8], ["91012", 49.8], ["91017", 54.8],
    ["91020", 59.8], ["91024", 64.8], ["93007", 69.8], ["91029", 74.8], ["97014", 79.8],
    ["10006", 84.8], ["20", 89.8], ["20021", 94.8], ["2", 100.0]];
const MACHINES = [["LDI-01", 16.6], ["LDI-02", 33.2], ["LDI-03", 44.1], ["LDI-04", 55.0],
    ["LDI-05", 72.2], ["LDI-06", 89.3], ["LDI-07", 93.0], ["LDI-08", 96.7],
    ["LDI-09", 98.4], ["LDI-10", 100.0]];
// alignment codes correlated to PE/JE out-of-tolerance (misalignment <-> PE error)
const ALIGN_CODES = ["90001", "90004", "90005", "90012", "90013"];
const RATE_PER_TICK = 0.01194 * 20 * (15 / 20); // unchanged overall pacing, noise share only

function pick(table) {
    const x = Math.random() * 100;
    for (const [v, c] of table) if (x <= c) return v;
    return table[table.length - 1][0];
}
function poissonCount(rate) {
    let n = 0, L = Math.exp(-rate), p = 1;
    do { p *= Math.random(); n++; } while (p > L);
    return n - 1;
}
// relatedLogId: the literal ldi_data.log_id of the telemetry row that
// triggered this alarm, when known (condition-driven codes only -- noise
// codes aren't tied to any specific board, so they pass null and let
// migration 051's trigger fall back to its nearest-match heuristic).
// World-Class Audit Priority 3: production-grade exact event linkage.
function newRow(eq, code, ts, relatedLogId) {
    return {
        logid: 'SIM-ALM-' + ts.getTime() + '-' + eq + '-' + code + '-' + Math.floor(Math.random() * 1e6),
        logdate: ts.toISOString(),
        errorcode: code,
        errortime: ts.toISOString().replace('T', ' ').substring(0, 19),
        equipmentid: eq,
        factory: Math.random() < 0.75 ? '2' : '3',
        process: ['DF INNER', 'DF OUTER', 'SM'][Math.floor(Math.random() * 3)],
        related_log_id: relatedLogId || null
    };
}

const rows = [];
const now = Date.now();

// ── background noise (unconditioned, real historical distribution) ──
const nNoise = poissonCount(RATE_PER_TICK);
for (let k = 0; k < nNoise; k++) {
    rows.push(newRow(pick(MACHINES), pick(NOISE_CUM), new Date(now - Math.floor(Math.random() * 9000))));
}

// ── condition-driven alarms: only fire when telemetry is actually out of
//    spec right now, using the same thresholds as v_ldi_alarm_context ──
const sql = `
    SELECT DISTINCT ON (eqp_id) eqp_id, process, temperature, humidity,
           pe_1, je_1, scan_speed, log_id
    FROM public.ldi_data
    WHERE time > NOW() - INTERVAL '3 minutes'
    ORDER BY eqp_id, time DESC`;

pool.query(sql, [], function (err, result) {
    if (err) { node.error('Alarm sim telemetry query failed: ' + err.message); return; }
    const ts = new Date();
    // ~25%/tick per condition so a persistently out-of-spec machine doesn't
    // fire an alarm on literally every 10s tick while the fault holds
    const fires = () => Math.random() < 0.25;
    for (const r of (result.rows || [])) {
        if ((r.temperature < 20 || r.temperature > 24 || r.humidity < 50 || r.humidity > 60) && fires()) {
            rows.push(newRow(r.eqp_id, '91008', ts, r.log_id));
        }
        if ((Math.abs(r.pe_1) > 10 || Math.abs(r.je_1) > 10) && fires()) {
            rows.push(newRow(r.eqp_id, ALIGN_CODES[Math.floor(Math.random() * ALIGN_CODES.length)], ts, r.log_id));
        }
        if ((r.scan_speed > 450 || r.scan_speed <= 0) && fires()) {
            rows.push(newRow(r.eqp_id, '70004', ts, r.log_id));
        }
    }

    if (rows.length === 0) { node.status({ fill: 'grey', shape: 'ring', text: 'no alarm' }); return; }
    node.status({ fill: 'yellow', shape: 'dot',
        text: rows.length + ' alarm: ' + rows.map(r => r.errorcode).join(',') });
    node.send({ payload: rows });
});
return null;

const pool = global.get('pgPool');
const rows = msg.payload || [];
if (!pool || rows.length === 0) return null;
const cols = ['logid','logdate','errorcode','errortime','equipmentid','factory','process','related_log_id'];
const ph = rows.map((_, i) => '(' + cols.map((_, j) => '$' + (i * cols.length + j + 1)).join(',') + ')').join(',');
const params = [];
for (const r of rows) for (const c of cols) params.push(r[c]);
const sql = 'INSERT INTO public.ldi_alarm_log (' + cols.join(',') + ') VALUES ' + ph +
            ' ON CONFLICT (logdate, logid) DO NOTHING';
pool.query(sql, params, function (err) {
    if (err) { node.error('Alarm sim INSERT failed: ' + err.message); return; }
    node.log('Alarm sim: inserted ' + rows.length);
});
return null;

const apiKey = global.get('INGEST_API_KEY') || 'ims-secret-key';
const incomingKey = msg.req?.headers?.['x-api-key'] || '';
if (incomingKey !== apiKey) {
    msg.statusCode = 401;
    msg.payload = { error: 'Unauthorized' };
    return msg;
}

if (!msg.payload || !Array.isArray(msg.payload)) {
    msg.statusCode = 400;
    msg.payload = { error: 'Payload must be a JSON array' };
    return msg;
}

// World-Class QA (2026-08-06): the server is the single source of truth
// for log_id, exactly like it already is for ingestion time (NOW() below)
// -- a live-machine/MES integration should not have to replicate the
// simulator's bespoke SIM-... id scheme just to get correct RCA linkage.
// Trust a caller-supplied log_id when present; otherwise derive a stable
// id from the row's own natural key (eqp_id+mo+board_no -- the same
// physical board-scan event will carry the same key on every retry, so
// ON CONFLICT (log_id, "time") DO NOTHING still dedupes correctly). Only
// fall back to a random id when that natural key is incomplete, so a row
// is never silently dropped for lacking one.
function genLogId(eqp_id, mo, board_no, rawLogId) {
    if (rawLogId) return rawLogId;
    if (mo && board_no !== null && board_no !== undefined && board_no !== '') {
        return 'LDI-' + eqp_id + '-' + mo + '-' + board_no;
    }
    return 'LDI-' + eqp_id + '-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
}

msg._ldiBatch = [];
const num = v => (v === 0) ? 0 : (Number(v) || null);
const int = v => (v === 0) ? 0 : (parseInt(v) || null);
for (const item of msg.payload) {
    if (!item || !item.eqp_id) continue;
    const eqp_id = String(item.eqp_id);
    const mo = String(item.mo || '');
    const board_no = int(item.board_no);
    const rawLogId = (item.log_id !== undefined && item.log_id !== null) ? String(item.log_id).trim() : '';
    msg._ldiBatch.push({
        eqp_id,
        factory: String(item.factory || ''),
        process: String(item.process || ''),
        mo,
        fpn: String(item.fpn || ''),
        layer_name: String(item.layer_name || ''),
        resist_dosage: num(item.resist_dosage),
        scale_x: num(item.scale_x),
        scale_y: num(item.scale_y),
        temperature: num(item.temperature),
        humidity: num(item.humidity),
        scan_speed: num(item.scan_speed),
        air_vacuum: num(item.air_vacuum),
        thickness: num(item.thickness),
        board_no,
        total_board: int(item.total_board),
        total_time: num(item.total_time),
        filmno: String(item.filmno || ''),
        board_id: String(item.board_id || ''),
        resist: item.resist ? String(item.resist) : null,
        state: item.state !== false,
        scale_mode: String(item.scale_mode || ''),
        pe_1: num(item.pe_1),
        pe_2: num(item.pe_2),
        pe_3: num(item.pe_3),
        pe_4: num(item.pe_4),
        pe_5: num(item.pe_5),
        pe_6: num(item.pe_6),
        je_1: num(item.je_1),
        je_2: num(item.je_2),
        je_3: num(item.je_3),
        je_4: num(item.je_4),
        pe_setting: num(item.pe_setting),
        je_setting: num(item.je_setting),
        log_id: genLogId(eqp_id, mo, board_no, rawLogId)
    });
}


if (msg._ldiBatch.length === 0) {
    msg.statusCode = 200;
    msg.payload = { message: 'Empty batch' };
    return msg;
}

const cols = [
    'factory', 'process', 'eqp_id', 'mo', 'fpn', 'layer_name', 'resist_dosage', 'scale_x', 'scale_y', 
    'temperature', 'humidity', 'scan_speed', 'air_vacuum', 'thickness', 'board_no', 'total_board', 
    'total_time', 'filmno', 'board_id', 'resist', 'state', 'scale_mode', 
    'pe_1', 'pe_2', 'pe_3', 'pe_4', 'pe_5', 'pe_6', 
    'je_1', 'je_2', 'je_3', 'je_4', 'pe_setting', 'je_setting', 'log_id'
];

let params = [];
const placeholders = msg._ldiBatch.map((row, i) => {
    const b = i * cols.length;
    cols.forEach(col => params.push(row[col]));
    const p = cols.map((_, j) => `$${b + j + 1}`).join(',');
    return `(NOW(), ${p})`;
}).join(',');

msg.query = `INSERT INTO public.ldi_data ("time", ${cols.join(',')}) VALUES ${placeholders} ON CONFLICT (log_id, "time") DO NOTHING;`;
msg.params = params;


const pool = global.get('pgPool');
if (pool) {
    pool.query(msg.query, msg.params, (err) => {
        if (err) {
            node.error('LDI INSERT failed: ' + err.message);
        }
    });
}

msg.statusCode = 200;
msg.payload = { message: "LDI Batch received" };
return msg;

const err = msg.error?.message || 'Unknown error';
node.error('LDI INSERT failed: ' + err);
msg.statusCode = 500;
msg.payload = { error: err };
return msg;

// ══════════════════════════════════════════════════════════════════
// LDI LIVE SIMULATOR — Ornstein-Uhlenbeck mean-reverting sensor model
